contributions.text:
{
  "reading": "Thraben Inspector fills the zero-one-drop hole and its Clue is both a draw (Shabraz counter) and a sacrificed noncreature artifact. The cleanest slot is Bard, King of Dale: a 6-drop whose draw text is the same as Teferi's Ageless Insight (kept in study 017), with card-advantage already at 26 copies against a target of >= 10. A land cut is refused: Temple of Epiphany out leaves U and R one source short, and it costs +2.4 pts missed drop by T5.",
  "log_entries_read": ["006", "009"],
  "axes_engaged": [
    {"axis": "card-advantage", "verdict": "strength", "measured": {"value": "26 copies"}, "reading": "Far over target. Losing one draw doubler takes nothing the deck is short of."},
    {"axis": "mana-base", "verdict": "adequate", "measured": {"value": "37 copies"}, "reading": "Inside 36-38, but a cut to 36 that removes a UR land makes U and R short."}
  ],
  "cut_candidates": [
    {"card": "Bard, King of Dale", "why": "A 6-drop that does nothing on the board early. Its draw doubling repeats Teferi's Ageless Insight, which costs 4.", "cost_of_cutting": "Goldfish, one instrument, 10,000 paired games: damage @T10 145.2 -> 135.3 [-11.5, -8.2]; hoard @T10 2.06 -> 1.64 [-0.55, -0.29], from its token doubling; extra cards by T8 19.4 -> 18.9. Also lost: a Human body with reach and vigilance, and any stacking with Ageless Insight (needs a stack scenario). The goldfish cannot price its defence.", "orphans_stack": [], "difficulty": "contested"},
    {"card": "Consecrated Sphinx", "why": "The other 6-drop. Ranked second only. Cutting it frees a Game Changer slot.", "cost_of_cutting": "Stack 009, a checker-passed kill under Wheel of Fortune, stops having a host card. Goldfish: damage @T10 -12.4 [-14.1, -10.8], extra cards by T8 -1.3, finisher wheel by T8 -0.6 pts. Not recommended.", "orphans_stack": [], "difficulty": "painful"}
  ],
  "add_candidates": [
    {"card": "Thraben Inspector", "closes": "curve", "source": "prompt", "why": "The deck's only one-drop creature. Its Clue is a draw for Shabraz and fodder for Jaws.", "natural_cut": "Bard, King of Dale"}
  ],
  "open_questions": [
    {"question": "Do Teferi's Ageless Insight and Bard, King of Dale stack, so one extra draw becomes four?", "settled_by": "resolve-stack", "why_it_matters": "If they stack, Bard is a multiplier and not a redundant copy, and the cut gets harder."}
  ],
  "gaps": ["The goldfish has no opponents, so it cannot price Bard's reach/vigilance body or Thraben's chump blocks.", "White is 19 sources against a target of 22. Thraben on turn 1 is 0.790 from lands, and cutting Bard does not change that.", "Rows came from the branch champion; goldfish_metrics/mana_analysis are stale against cards.json (audit note)."]
}
